sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var currentUser = g_user.userID;// current userid
    var currentRecord = g_form.getUniqueValue();// current record sysid

    var gaAssignedTo = new GlideAjax("x_hsb11_mss_fund_0.MSS_Funds_Client_Utils");// check if user is assigned to any of the task with current case
    gaAssignedTo.addParam('sysparm_name', 'checkTaskAssignedTo');
    gaAssignedTo.addParam('sysparm_caseId', currentRecord);
    gaAssignedTo.addParam('sysparm_userId', currentUser);
    gaAssignedTo.getXML(callBackFunction);

    function callBackFunction(response) {
        var ans = response.responseXML.documentElement.getAttribute('answer');
        if (ans == 'true')
            g_form.setDisabled('final_check_status', true);//if user worked on task, disable final check for user
    }
}
